	@PostLoad
	private void afterLoad() {
		rebuildCurrentStatus();
	}

	/**
	 * Documents this component's behavior and responsibilities.
	 */
	public void assignOperator(MunicipalOperator operator) {

		if (operator == null) {
			throw new IllegalArgumentException("The operator must not be null.");
		}

		this.operator = operator;
	}

	/**
	 * Documents this component's behavior and responsibilities.
	 */
	public void updateStatus() {

		if (operator == null) {
			throw new IllegalStateException(
					"Status cannot be updated without an assigned municipal operator."
			);
		}

		initializeCurrentStatusIfNeeded();

		String statusPrevious = currentStatusName;

		currentStatus.updateStatus(this);

		if (isBlank(currentStatusName) || currentStatusName.equals(statusPrevious)) {
			throw new IllegalStateException("The report status was not updated.");
		}

		registerStatusUpdate();
	}

	/**
	 * Documents this component's behavior and responsibilities.
	 */
	public void addInternalNote(String noteText,
	                                MunicipalOperator operator) {

		if (isBlank(noteText)) {
			throw new IllegalArgumentException("Internal note text must not be empty.");
		}

		if (operator == null) {
			throw new IllegalArgumentException("The operator must not be null.");
		}

		InternalNote internalNote = new InternalNote(
				noteText,
				new Date(),
				this,
				operator
		);

		internalNotes.add(internalNote);
	}

	/**
	 * Documents this component's behavior and responsibilities.
	 */
	void setStatusCurrent(ReportStatus newStatus,
	                      String nameNewStatus,
	                      boolean editable) {

		if (newStatus == null) {
			throw new IllegalArgumentException("Current status must not be null.");
		}

		if (isBlank(nameNewStatus)) {
			throw new IllegalArgumentException("New status name must not be empty.");
		}

		this.currentStatus = newStatus;
		this.currentStatusName = nameNewStatus.trim();
		this.citizenEditable = editable;
	 * Documents this component's behavior and responsibilities.
	 */
	private void registerStatusUpdate() {

		if (operator == null) {
			throw new IllegalStateException(
					"The update cannot be recorded without an assigned municipal operator."
			);
		}

		StatusUpdate updateStatus = new StatusUpdate(
				new Date(),
				currentStatusName,
				this,
				operator
		);

		statusUpdates.add(updateStatus);
	}

	/**
	 * Documents this component's behavior and responsibilities.
	 */
	private void initializeStatusSubmitted() {
		this.currentStatusName = STATUS_SUBMITTED;
		this.currentStatus = new Submitted();
		this.citizenEditable = true;
	}

	/**
	 * Documents this component's behavior and responsibilities.
	 */
	private void initializeCurrentStatusIfNeeded() {
		if (currentStatus == null) {
			rebuildCurrentStatus();
		}
	}

	/**
	 * Documents this component's behavior and responsibilities.
	 */
	private void rebuildCurrentStatus() {

		if (isBlank(currentStatusName)) {
			initializeStatusSubmitted();
			return;
		}

		switch (currentStatusName) {
			case STATUS_SUBMITTED:
				this.currentStatus = new Submitted();
				this.citizenEditable = true;
				break;

			case STATUS_ASSIGNED:
				this.currentStatus = new Assigned();
				this.citizenEditable = false;
				break;

			case STATUS_IN_PROGRESS:
				this.currentStatus = new InProgress();
				this.citizenEditable = false;
				break;

			case STATUS_RESOLVED:
				this.currentStatus = new Resolved();
				this.citizenEditable = false;
				break;

			default:
				throw new IllegalStateException(
						"Invalid current status: " + currentStatusName
				);
		}
	}

	/**
	 * Documents this component's behavior and responsibilities.
	 */
	public boolean isCurrentStatusNotifiable() {
		initializeCurrentStatusIfNeeded();

