public class SystemServicesController {

	private UserRegistrationController controllerRegistrationUser;
	private ReportCreationController controllerCreationReport;
	private ReportReviewController controllerReviewReports;
	private ReportDetailsController controllerDetailsReport;
	private ReportStatusUpdateController controllerStatusUpreportData;
	private InternalNoteController controllerInternalNote;
	private ActivityMonitoringController controllerMonitoringActivity;

	/**
	 * Documents this component's behavior and responsibilities.
	 */
	public SystemServicesController() {
		this.controllerRegistrationUser = new UserRegistrationController();
		this.controllerCreationReport = new ReportCreationController();
		this.controllerReviewReports = new ReportReviewController();
		this.controllerDetailsReport = new ReportDetailsController();
		this.controllerStatusUpreportData = new ReportStatusUpdateController();
		this.controllerInternalNote = new InternalNoteController();
		this.controllerMonitoringActivity = new ActivityMonitoringController();
	}
	public boolean registerUser(Map<String, Object> registrationData) {
		if (registrationData == null) {
			return false;
		}

		try {
			Long registeredUserId = controllerRegistrationUser.requestRegistrationUser(registrationData);
			return registeredUserId != null;

		} catch (IllegalArgumentException e) {
			// Implementation note for the English standalone variant.
			throw e;
		} catch (RuntimeException e) {
			System.err.println("[SystemServicesController] Unexpected error during user registration.");
			e.printStackTrace();
			return false;
		}
	}

	/**
	 * Documents this component's behavior and responsibilities.
	 */
public class ReportStatusUpdateController {

	private UserService userService;
	private ReportService reportService;
	private NotificationController notificationController;

	/**
	 * Documents this component's behavior and responsibilities.
	 */
	public ReportStatusUpdateController() {
		this.userService = new UserService();
		this.reportService = new ReportService();
		this.notificationController = new NotificationController();
	}

	/**
	 * Documents this component's behavior and responsibilities.
	/**
	 * Documents this component's behavior and responsibilities.
	 */
	public String applyNewStatus(
			Long userId,
			Long reportId
	) {

		if (userId == null || reportId == null) {
			return null;
		}

		return reportService.updateReportStatus(
				userId,
				reportId
		);
	}

	/**
	 * Documents this component's behavior and responsibilities.
	 */
	public void requestNotification(
			Long reportId,
			String newStatus
	) {

		if (reportId == null || isBlank(newStatus)) {
			return;
		}

		notificationController.verifyNotifiableStatus(
				reportId,
				newStatus
		);
	}

	/**
	 * Documents this component's behavior and responsibilities.
	 */
	private boolean isBlank(String value) {
		return value == null || value.trim().isEmpty();
	}
        public String updateReportStatus(
                Long userId,
                Long reportId
        ) {

            if (userId == null || reportId == null) {
                return null;
            }

            try {
                MunicipalOperator operator = persistenceService.findById(
                        MunicipalOperator.class,
                        userId
                );

                if (operator == null) {
                    return null;
                }

                Report report = persistenceService.findById(
                        Report.class,
                        reportId
                );

                if (report == null) {
                    return null;
                }

                String statusPrevious = report.getCurrentStatusName();

                report.assignOperator(operator);
                report.updateStatus();

                String newStatus = report.getCurrentStatusName();

                if (isBlank(newStatus) || newStatus.equals(statusPrevious)) {
                    return null;
                }

                persistenceService.update(report);

                return newStatus;

            } catch (RuntimeException e) {
                System.err.println("[ReportService] Error while updating status: "
                        + e.getMessage());
                return null;
        }

        /**
         * Documents this component's behavior and responsibilities.
         */
        public Long generateStatusChangeNotification(
                Long reportId,
                String newStatus
        ) {

            if (reportId == null || isBlank(newStatus)) {
                return null;
            }

            // Implementation note for the English standalone variant.
            if (!verifyNotifiableStatus(reportId, newStatus)) {
                return null;
            }

            // Implementation note for the English standalone variant.
            Report report = persistenceService.findById(
                    Report.class,
                    reportId
            );

            if (report == null || report.getCitizenReporting() == null) {
                return null;
            }

            String message = "Report "
                    + reportId
                    + " was updated to status: "
                    + formatStatusForMessage(newStatus);

            try {
                Notification notification = new Notification(
                        new Date(),
                        message,
                        newStatus,
                        report.getCitizenReporting(),
                        report
                );

                persistenceService.save(notification);

                return notification.getNotificationId();

