	public boolean registerUser(Map<String, Object> registrationData) {
		if (registrationData == null) {
			return false;
		}

		try {
			Long registeredUserId = controllerRegistrationUser.requestRegistrationUser(registrationData);
			return registeredUserId != null;

		} catch (IllegalArgumentException e) {
			// Implementation note for the English standalone variant.
			throw e;
		} catch (RuntimeException e) {
			System.err.println("[SystemServicesController] Unexpected error during user registration.");
			e.printStackTrace();
			return false;
		}
	}

