        public String updateReportStatus(
                Long userId,
                Long reportId
        ) {

            if (userId == null || reportId == null) {
                return null;
            }

            try {
                MunicipalOperator operator = persistenceService.findById(
                        MunicipalOperator.class,
                        userId
                );

                if (operator == null) {
                    return null;
                }

                Report report = persistenceService.findById(
                        Report.class,
                        reportId
                );

                if (report == null) {
                    return null;
                }

                String statusPrevious = report.getCurrentStatusName();

                report.assignOperator(operator);
                report.updateStatus();

                String newStatus = report.getCurrentStatusName();

                if (isBlank(newStatus) || newStatus.equals(statusPrevious)) {
                    return null;
                }

                persistenceService.update(report);

                return newStatus;

            } catch (RuntimeException e) {
                System.err.println("[ReportService] Error while updating status: "
                        + e.getMessage());
                return null;
        }

        /**
         * Documents this component's behavior and responsibilities.
         */
        public Long generateStatusChangeNotification(
                Long reportId,
                String newStatus
        ) {

            if (reportId == null || isBlank(newStatus)) {
                return null;
            }

            // Implementation note for the English standalone variant.
            if (!verifyNotifiableStatus(reportId, newStatus)) {
                return null;
            }

            // Implementation note for the English standalone variant.
            Report report = persistenceService.findById(
                    Report.class,
                    reportId
            );

            if (report == null || report.getCitizenReporting() == null) {
                return null;
            }

            String message = "Report "
                    + reportId
                    + " was updated to status: "
                    + formatStatusForMessage(newStatus);

            try {
                Notification notification = new Notification(
                        new Date(),
                        message,
                        newStatus,
                        report.getCitizenReporting(),
                        report
                );

                persistenceService.save(notification);

                return notification.getNotificationId();

